<?php

declare(strict_types=1);

require_once __DIR__ . '/../includes/bootstrap.php';
requireLogin('../login.php');
requireRole('super_admin', '../login.php');
$pdo = Database::getInstance();
$stats=['users'=>(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn(),'news'=>(int)$pdo->query('SELECT COUNT(*) FROM news')->fetchColumn(),'pending'=>(int)$pdo->query("SELECT COUNT(*) FROM news WHERE status='pending'")->fetchColumn(),'published'=>(int)$pdo->query("SELECT COUNT(*) FROM news WHERE status='published'")->fetchColumn()];
$recent=$pdo->query('SELECT n.id,n.title,n.status,n.is_anonymous,n.image,n.created_at,u.username,c.name AS category_name FROM news n LEFT JOIN users u ON u.id=n.author_id LEFT JOIN categories c ON c.id=n.category_id ORDER BY n.created_at DESC LIMIT 10')->fetchAll();
$flash=getFlash();$siteName=getSetting('site_name',APP_NAME);
?>
<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Admin Dashboard | <?= e($siteName) ?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="../assets/css/style.css"></head><body class="bg-light"><div class="container-fluid"><div class="row"><aside class="col-lg-2 dashboard-sidebar p-3"><h4 class="text-white"><?= e($siteName) ?></h4><p class="text-white-50 small">Super Admin Control Center</p><nav class="nav flex-column gap-1"><a class="active" href="index.php">Dashboard</a><a href="../submit.php">➕ Write News</a><a href="news.php">Moderate News</a><a href="settings.php">Site Settings</a><a href="users.php">Users</a><a href="categories.php">Categories</a><a href="menus.php">Menus</a><a href="../index.php">Public Site</a><a href="../logout.php">Logout</a></nav></aside><main class="col-lg-10 p-4"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-4"><div><h2>Super Admin Dashboard</h2><p class="text-muted mb-0">Control publishing, users, branding and moderation.</p></div><a href="../submit.php" class="btn btn-success">➕ Post New News</a></div><?php if($flash): ?><div class="alert alert-<?= e((string)$flash['type']) ?>"><?= e((string)$flash['message']) ?></div><?php endif; ?><div class="row g-3 mb-4"><?php foreach([['Users',$stats['users'],'primary'],['All News',$stats['news'],'dark'],['Pending',$stats['pending'],'warning'],['Published',$stats['published'],'success']] as $card): ?><div class="col-sm-6 col-xl-3"><div class="card border-0 shadow-sm"><div class="card-body"><small class="text-muted"><?= e($card[0]) ?></small><div class="display-6 fw-bold text-<?= e($card[2]) ?>"><?= (int)$card[1] ?></div></div></div></div><?php endforeach; ?></div><div class="card border-0 shadow-sm"><div class="card-body"><div class="d-flex justify-content-between mb-3"><h4>Recent News</h4><a href="news.php" class="btn btn-sm btn-outline-primary">Manage All</a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Story</th><th>Author</th><th>Category</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$recent): ?><tr><td colspan="5" class="text-center text-muted">No news yet.</td></tr><?php endif; ?><?php foreach($recent as $item): ?><tr><td><?php if($item['image']): ?><img class="thumb me-2" src="../<?= e((string)$item['image']) ?>" alt=""><?php endif; ?><a href="news-edit.php?id=<?= (int)$item['id'] ?>"><?= e((string)$item['title']) ?></a></td><td><?= (int)$item['is_anonymous']===1?'Anonymous':e((string)($item['username']??'Unknown')) ?></td><td><?= e((string)($item['category_name']??'General')) ?></td><td><span class="badge text-bg-secondary"><?= e((string)$item['status']) ?></span></td><td><a class="btn btn-sm btn-outline-primary" href="news-edit.php?id=<?= (int)$item['id'] ?>">Edit</a></td></tr><?php endforeach; ?></tbody></table></div></div></div></main></div></div></body></html>
